argv:
$ErrorActionPreference='Stop'
$head=([string](& git.exe -C 'E:\WebAIBridge' rev-parse HEAD)).Trim()
Write-Output ('PROD_HEAD='+$head)
Write-Output ('R68_HEAD='+([string](& git.exe -C 'E:\WebAIBridge-R68-OBSERVABILITY-20261014-GPT6' rev-parse HEAD)).Trim())
Write-Output ('R68_TRACKED_DIRTY='+@(& git.exe -C 'E:\WebAIBridge-R68-OBSERVABILITY-20261014-GPT6' status --porcelain=v1 --untracked-files=no).Count)
foreach($port in @(17448,17450)) {
try { $t=Invoke-RestMethod -Uri ('http://127.0.0.1:'+ $port + $(if($port -eq 17450){'/api/live'}else{'/api/operator-lifecycle'})) -TimeoutSec 2
if($port -eq 17450){
Write-Output ('VIEWER_CONTRACT='+$t.contract)
Write-Output ('VIEWER_OPEN='+$t.openCount)
Write-Output ('VIEWER_UNKNOWN='+$t.unregisteredOpenCount)
Write-Output ('VIEWER_SCAN_OK='+$t.scanComplete)
}else{ Write-Output ('PROD_LIFECYCLE='+$t.mode) }
}catch{Write-Output ('HTTP_'+$port+'_UNAVAILABLE='+$_.Exception.GetType().Name)}
}
$startup=[Environment]::GetFolderPath('Startup')
Write-Output ('STARTUP_DIR_AVAILABLE='+[bool](Test-Path $startup))
Write-Output ('VIEWER_STARTUP_EXISTS='+(Test-Path (Join-Path $startup 'WebAIBridge-R68-Live.lnk')))
